systemLandscape "SystemLandscape" "All systems and people in the order management domain" {
    include *
    autoLayout
    title "Order Management - System Landscape"
}

systemContext oms "SystemContext" "The Order Management System and its actors" {
    include *
    autoLayout
    title "Order Management System - Context"
}

container oms "Containers" "Containers within the Order Management System" {
    include *
    autoLayout
    title "Order Management System - Containers"
}

component oms.api "ApiComponents" "Components within the API container" {
    include *
    autoLayout
    title "API - Components"
}

dynamic oms "PlaceOrder" "Placing an order end to end" {
    customer -> oms.webApp "browses the catalogue and places orders in" "HTTPS"
    oms.webApp -> oms.api "submits orders and queries order status via" "HTTPS/JSON"
    oms.api -> oms.orderDb "persists and retrieves orders in" "SQL"
    oms.api -> paymentGateway "authorises and captures card payments with" "HTTPS/JSON"
    oms.api -> oms.queue "publishes order-placed events to" "AMQP"
    oms.worker -> oms.queue "consumes order-placed events from" "AMQP"
    oms.worker -> inventorySystem "reserves stock against" "HTTPS/JSON"
    autoLayout
    title "Place Order - Dynamic"
}

deployment oms "Production" "ProductionDeployment" "Production deployment of the Order Management System" {
    include *
    autoLayout
    title "Order Management System - Production Deployment"
}

